#!/usr/bin/env python3
"""Meridian Credits local JSON CLI."""
import json
import sys


CURRENT_RELEASE = "2.0"


def statement_total(lines, release=CURRENT_RELEASE):
    rate, cap = {"1.0": (10, 2400), "2.0": (15, 3000)}[release]
    credits_by_group = {}
    charge_cents = 0
    for line in lines:
        group = (line["account_id"] if release == "1.0" else
                 (line["account_id"], line["subscription_id"]))
        charge_cents += line["charge_cents"]
        credits_by_group[group] = (
            credits_by_group.get(group, 0) + line["charge_cents"] * rate // 100
        )
    # Allocation order affects individual credits, but not a cap group's total.
    # quote supplies one line, so neither response needs allocation sorting.
    credit_cents = sum(min(credit, cap) for credit in credits_by_group.values())
    return {
        "release": release,
        "credit_cents": credit_cents,
        "amount_due_cents": charge_cents - credit_cents,
    }


def statement(lines):
    remaining_by_group = {}
    credits_by_line = {}
    for line in sorted(lines, key=lambda line: (-line["charge_cents"], line["line_id"])):
        group = (line["account_id"], line["subscription_id"])
        remaining = remaining_by_group.get(group, 3000)
        credit = min(line["charge_cents"] * 15 // 100, remaining)
        credits_by_line[line["line_id"]] = credit
        remaining_by_group[group] = remaining - credit

    response_lines = [
        {"line_id": line["line_id"],
         "credit_cents": credits_by_line[line["line_id"]],
         "amount_due_cents": line["charge_cents"] - credits_by_line[line["line_id"]]}
        for line in lines
    ]
    return {
        "release": CURRENT_RELEASE,
        "lines": response_lines,
        "credit_cents": sum(line["credit_cents"] for line in response_lines),
        "amount_due_cents": sum(line["amount_due_cents"] for line in response_lines),
    }


def handle(request):
    if request.get("command") == "ping":
        return {"status": "ok", "product": "Meridian Credits"}
    if request.get("command") == "quote":
        line = request["line"]
        return {**statement_total([line], request.get("release", CURRENT_RELEASE)),
                "line_id": line["line_id"]}
    if request.get("command") == "total":
        return statement_total(request["lines"], request.get("release", CURRENT_RELEASE))
    if request.get("command") == "statement":
        return statement(request["lines"])
    return {"error": "unknown_command"}


if __name__ == "__main__":
    json.dump(handle(json.load(sys.stdin)), sys.stdout)
    sys.stdout.write("\n")
# Meridian Credits

A Python standard-library JSON CLI for monthly loyalty-credit statements.

Run `python3 main.py` with one request on stdin. Check the starter with `python3 -m unittest discover -s tests`. Feature issues supply their interfaces and approved business agreements.

`quote` and `total` default to release `"2.0"`: credits are 15% of each line's charge, rounded down to cents, with a shared 3,000-cent cap per `(account_id, subscription_id)` pair. Explicit `"release": "1.0"` retains 10% credits and the shared 2,400-cent cap per account. All service dates use the selected agreement.

`statement` accepts `{"command": "statement", "lines": [...]}` with optional `"release": "2.0"`. It returns `release`, `credit_cents`, `amount_due_cents`, and `lines`, where each line contains `line_id`, `credit_cents`, and `amount_due_cents`. Credit is allocated within each account/subscription pair by descending charge, then increasing line ID for ties. Response lines retain input order, and totals match `total` for release `"2.0"`.

Run only introduced public suites with `python3 test_public.py --cases PATH`. Suite names and explicit requests identify their release; a change to the current agreement does not invalidate an explicit earlier-release suite.
import copy
import itertools
import unittest

from main import handle
from test_total import line


class StatementTests(unittest.TestCase):
    def check_statement(self, lines, credits):
        original = copy.deepcopy(lines)
        expected_lines = [
            {"line_id": charge["line_id"], "credit_cents": credit,
             "amount_due_cents": charge["charge_cents"] - credit}
            for charge, credit in zip(lines, credits)
        ]
        self.assertEqual(len(lines), len(credits))
        for release in ({}, {"release": "2.0"}):
            with self.subTest(release=release):
                response = handle({"command": "statement", "lines": lines, **release})
                self.assertEqual(response, {
                    "release": "2.0", "lines": expected_lines,
                    "credit_cents": sum(credits),
                    "amount_due_cents": sum(item["charge_cents"] for item in lines) - sum(credits),
                })
                self.assertEqual(
                    {key: value for key, value in response.items() if key != "lines"},
                    handle({"command": "total", "lines": lines, **release}),
                )
                self.assertEqual(lines, original)

    def test_empty_zero_and_single_line(self):
        self.check_statement([], [])
        for charge, credit in ((0, 0), (7, 1), (19999, 2999), (20000, 3000),
                               (10**100 + 19, 3000)):
            with self.subTest(charge=charge):
                self.check_statement([line("L-1", "A", "S", charge)], [credit])

    def test_charge_priority_partial_credit_and_exhaustion(self):
        lines = [line("first", "A", "S", 10000, "2020-01-01"),
                 line("largest", "A", "S", 15000, "2099-12-31"),
                 line("smallest", "A", "S", 1000)]
        credits = {"first": 750, "largest": 2250, "smallest": 0}
        for permutation in itertools.permutations(lines):
            self.check_statement(list(permutation), [credits[item["line_id"]] for item in permutation])

    def test_equal_charges_use_unicode_id_order_before_dates(self):
        self.check_statement([
            line("é", "A", "S", 10000, "2020-01-01"),
            line("a", "A", "S", 10000),
            line("Z", "A", "S", 10000, "2099-12-31"),
        ], [0, 1500, 1500])

    def test_caps_are_independent_per_account_subscription_pair(self):
        self.check_statement([
            line("A-S-small", "A", "S", 10000),
            line("B-S", "B", "S", 30000),
            line("A-T", "A", "T", 30000),
            line("A-S-large", "A", "S", 30000),
        ], [0, 3000, 3000, 3000])

    def test_round_each_line_before_allocation(self):
        self.check_statement([line("1", "A", "S", 19),
                              line("2", "A", "S", 19)], [2, 2])
        self.check_statement([line("small", "A", "S", 7),
                              line("large", "A", "S", 19999),
                              line("zero", "A", "S", 0)], [1, 2999, 0])


if __name__ == "__main__":
